import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Using-PSPP.md","filePath":"manual-en/Using-PSPP.md","lastUpdated":1785684581000}'),n={name:"manual-en/Using-PSPP.md"};function i(r,e,h,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h2 id="_5-using-pspp" tabindex="-1">5 Using PSPP <a class="header-anchor" href="#_5-using-pspp" aria-label="Permalink to &quot;5 Using PSPP&quot;">​</a></h2><p>PSPP is a tool for the statistical analysis of sampled data. You can use it to discover patterns in the data, to explain differences in one subset of data in terms of another subset and to find out whether certain beliefs about the data are justified. This chapter does not attempt to introduce the theory behind the statistical analysis, but it shows how such analysis can be performed using PSPP.</p><p>For the purposes of this tutorial, it is assumed that you are using PSPP in its interactive mode from the command line. However, the example commands can also be typed into a file and executed in a post-hoc mode by typing ‘pspp file-name’ at a shell prompt, where file-name is the name of the file containing the commands. Alternatively, from the graphical interface, you can select File → New → Syntax to open a new syntax window and use the Run menu when a syntax fragment is ready to be executed. Whichever method you choose, the syntax is identical.</p><p>When using the interactive method, PSPP tells you that it’s waiting for your data with a string like PSPP&gt; or data&gt;. In the examples of this chapter, whenever you see text like this, it indicates the prompt displayed by PSPP, <em>not</em> something that you should type.</p><p>Throughout this chapter reference is made to a number of sample data files. So that you can try the examples for yourself, you should have received these files along with your copy of PSPP.1</p><blockquote><p><strong>Please note:</strong> Normally these files are installed in the directory /usr/local/share/pspp/examples. If however your system administrator or operating system vendor has chosen to install them in a different location, you will have to adjust the examples accordingly.</p></blockquote><table tabindex="0"><thead><tr><th>• Preparation of Data Files</th><th></th><th></th></tr></thead><tbody><tr><td>• Data Screening and Transformation</td><td></td><td></td></tr><tr><td>• Hypothesis Testing</td><td></td><td></td></tr></tbody></table><h4 id="footnotes" tabindex="-1">Footnotes <a class="header-anchor" href="#footnotes" aria-label="Permalink to &quot;Footnotes&quot;">​</a></h4><h5 id="_1" tabindex="-1">(1) <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;(1)&quot;">​</a></h5><p>These files contain purely fictitious data. They should not be used for research purposes.</p>',10)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
